# One reply per wager: an open dice bet, a wheel spin or a slots pull. Without `request_id` you
# get only the `game_log` of the refund. An open roulette bet is in `player.bets` too, so the
# dice refund returns it, with `place: "dice"`; it never has `request_id`.
# The object can have more keys than these (a TypedDict cannot say so).
BetRefund = TypedDict("BetRefund", {
    "response": "Literal[\"tavern_closing\"]",
    "place": "Literal[\"dice\", \"wheel\", \"slots\"]",
    "failed": "Literal[True]",
    "request_id": "Any",
    "reason": "Literal[\"tavern_closing\"]",
    "refund": "int",
})

# `bet` reply: All checks pass. Two `game_log` events: this one (`server.game_log.num`), then
# `server.game_log.bet_gold` with `{amount}` ("Bet: 100,000 gold", color `"gray"`). There is no
# `game_response` now.
BetDiceAccepted: TypeAlias = "LocalizedText"

# `bet` reply: At the end of the round, when the roll is on your side of `num`. Two `game_log`
# events: this one with the gross win, then `server.game_log.house_edge_gold` with `{amount:
# edge}` ("House edge: 2,000 gold", color `"gray"`).
BetDiceWon: TypeAlias = "LocalizedText"

# `bet` reply: At the end of the round, when the roll is not on your side.
BetDiceLost: TypeAlias = "LocalizedText"

# `bet` reply (With request_id): At the end of the round, after the `game_log`. It has no
# `failed` field for a loss: `success` is `true` and `won` is `false`.
# The object can have more keys than these (a TypedDict cannot say so).
BetDiceResult = TypedDict("BetDiceResult", {
    "response": "Literal[\"data\"]",
    "place": "Literal[\"dice\"]",
    "success": "Literal[True]",
    "request_id": "Any",
    "won": "bool",
    "roll": "float",
    "num": "float",
    "direction": "Literal[\"up\", \"down\"]",
    "wager": "int",
    "payout": "int",
    "net": "int",
    "edge": "int",
})

# `bet` reply: All checks pass. The server picks the slice now (`crypto.randomInt` over the 14
# slices of `G.games.wheel.slices`, 7 per side) and takes the stake. `phrase_args.side` is an
# object: the phrase of the side.
BetWheelAccepted: TypeAlias = "LocalizedText"

# `bet` reply: 4,000 ms later (`player.q.wheel`). `server.game_log.wheel_won` with the net win,
# or `server.game_log.wheel_lost` with the stake. `side` is the side of the slice.
BetWheelStopped: TypeAlias = "LocalizedText"

# `bet` reply (With request_id): After the `tavern` result.
# The object can have more keys than these (a TypedDict cannot say so).
BetWheelResult = TypedDict("BetWheelResult", {
    "response": "Literal[\"data\"]",
    "place": "Literal[\"wheel\"]",
    "success": "Literal[True]",
    "request_id": "Any",
    "won": "bool",
    "side": "Literal[\"sun\", \"moon\"]",
    "result": "Literal[\"sun\", \"moon\"]",
    "slice": "str",
    "wager": "int",
    "payout": "int",
    "net": "int",
    "edge": "float",
})

